--------------------------------------------------------
--  DDL for View TMP_VIEW
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "BCPMS_OWNER"."TMP_VIEW" ("PEOPLE_ID", "FIRST_NAME", "LAST_NAME", "MID_NAME", "OU_ORG_ID", "DIV_ORG_ID", "GRP_ORG_ID", "USERNAME", "EMAIL", "PHONE", "SUPERVISOR_YN", "LAST_UPDATE_DT", "IS_DIVISION_CHIEF", "IS_AO", "IS_AA", "IS_GROUP_LEADER", "STAFF_TYPE") AS 
  select "PEOPLE_ID","FIRST_NAME","LAST_NAME","MID_NAME","OU_ORG_ID","DIV_ORG_ID","GRP_ORG_ID","USERNAME","EMAIL","PHONE","SUPERVISOR_YN","LAST_UPDATE_DT","IS_DIVISION_CHIEF","IS_AO","IS_AA","IS_GROUP_LEADER","STAFF_TYPE" from nist_user_all
;
--------------------------------------------------------
--  DDL for View UV_REQUEST
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "BCPMS_OWNER"."UV_REQUEST" ("REQUEST_ID", "NOTES", "REQUESTER_ID", "REQUESTER_NAME", "CREATED_FOR", "CREATED_FOR_NAME", "CREATED_BY", "CREATED_BY_NAME", "CREATED_DATE", "UPDATED_BY", "UPDATED_BY_NAME", "UPDATED_DATE", "IS_SHOPPING_CART", "REFERENCE_ID", "DELIVER_ADDRESS", "SHIPPING_COST", "LATEST_REQUEST_STATUS_TYPE_ID", "ROUTE_STATUS_TYPE_NAME", "REQUISITION_NUMBER") AS 
  select 
    request_id,
    notes,
    requester_id,
    get_user_name(requester_id) as requester_name,
    created_for,
    get_user_name(created_for) as created_for_name,
    created_by,
    get_user_name(created_by) as created_by_name,
    created_date,
    updated_by,
    get_user_name(updated_by) as updated_by_name,
    updated_date,
    is_shopping_cart,
    reference_id,
    deliver_address,
    shipping_cost,
    latest_request_status_type_id,
    rst.route_status_type_name,
    requisition_number
from request r
inner join lkup_route_status_type rst on r.latest_request_status_type_id = rst.route_status_type_id
;
--------------------------------------------------------
--  DDL for View V_OBJCLASS
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "BCPMS_OWNER"."V_OBJCLASS" ("CODE", "DESCRIPTION") AS 
  select object1_code || '-' || object2_code as code, object4_descr as description from object4
where active_status = 'Y'
;
