--  DDL for Trigger AFTER_INSERT
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE TRIGGER "BCPMS_OWNER"."AFTER_INSERT" 
after insert
on "ROUTE_STATUS"
for each row
begin
    update request 
    set LATEST_REQUEST_STATUS_TYPE_ID = :new.route_status_type_id
    where request_id = :new.request_id;
end;    
/
ALTER TRIGGER "BCPMS_OWNER"."AFTER_INSERT" ENABLE;
--------------------------------------------------------
--  DDL for Procedure UP_GET_REQUISITION_NUMBER
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "BCPMS_OWNER"."UP_GET_REQUISITION_NUMBER" (p_division_code in varchar2, p_return_val out varchar2)
AS
    v_next_num integer := 1;
BEGIN
    select 
        next_number into v_next_num 
    from 
        requisition_number 
    where division_code = p_division_code for update;

    update requisition_number
    set next_number = next_number + 1
    where division_code = p_division_code;
    commit;

    p_return_val := p_division_code || substr(extract(year from add_months (SYSDATE(), + 3)), 4) || to_base_36(v_next_num);

    exception
        when NO_DATA_FOUND then
        begin        
            insert into requisition_number (division_code, next_number) 
            values (p_division_code, 2);
            v_next_num :=1;
            commit;
            p_return_val := p_division_code || substr(extract(year from add_months (SYSDATE(), + 3)), 4) || to_base_36(v_next_num);
        end;
END;

/
--------------------------------------------------------
--  DDL for Procedure UP_SAVE_DEFAULT_ROUTE
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "BCPMS_OWNER"."UP_SAVE_DEFAULT_ROUTE" (
    p_default_route default_route%ROWTYPE)
as

begin
    insert into default_route (people_id, reviewer, bankcard_approving_official, bankcard_holder)
    values (
        p_default_route.people_id, 
        p_default_route.reviewer, 
        p_default_route.bankcard_approving_official, 
        p_default_route.bankcard_holder);

exception
    WHEN DUP_VAL_ON_INDEX THEN
        update default_route 
        set reviewer = p_default_route.reviewer,
            bankcard_approving_official = p_default_route.bankcard_approving_official,
            bankcard_holder = p_default_route.bankcard_holder
        where people_id = p_default_route.people_id;
end;

/
--------------------------------------------------------
--  DDL for Function GET_USER
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "BCPMS_OWNER"."GET_USER" (p_people_id in NIST_USER_ALL.PEOPLE_ID%TYPE)
return NIST_USER_ALL%ROWTYPE
IS
l_user NIST_USER_ALL%ROWTYPE;
begin
    select * into l_user
    from NIST_USER_ALL 
    where people_id = p_people_id;
return l_user;
end;

/
--------------------------------------------------------
--  DDL for Function GET_USER_FROM_TOKEN
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "BCPMS_OWNER"."GET_USER_FROM_TOKEN" (p_token in USER_SESSION.TOKEN%TYPE)
return NIST_USER_ALL%ROWTYPE
IS
l_user NIST_USER_ALL%ROWTYPE;
begin
    select u.* into l_user
    from NIST_USER_ALL u
    inner join user_session us on u.people_id = us.people_id 
    where us.token = p_token;
return l_user;
end;

/
--------------------------------------------------------
--  DDL for Function GET_USER_NAME
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "BCPMS_OWNER"."GET_USER_NAME" (p_people_id in NIST_USER_ALL.PEOPLE_ID%TYPE)
return nvarchar2
IS
l_user_name nvarchar2(50);
begin
    select first_name || ' ' || last_name into l_user_name
    from NIST_USER_ALL 
    where people_id = p_people_id;
return l_user_name;
end;

/
--------------------------------------------------------
--  DDL for Function REQUISITION_NUM
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "BCPMS_OWNER"."REQUISITION_NUM" ( division_code in VARCHAR2 )
                  RETURN VARCHAR2 IS
BEGIN
    RETURN (division_code || substr(extract(year from add_months (SYSDATE(), + 3)), 4) || '-' || to_base_36(requisition_seq.nextval));
END;

/
--------------------------------------------------------
--  DDL for Function SEND_EMAIL
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "BCPMS_OWNER"."SEND_EMAIL" (
p_sender in nvarchar2, 
p_receip in nvarchar2,
p_cc in nvarchar2 := null,
p_subject nvarchar2,
p_message nvarchar2
)
RETURN VARCHAR2 
AS 
l_rc varchar2(1) := 'N';
--l_type varchar2(50) := 'text/plan; charset=us_ascii';
l_type varchar2(50) := 'text/html; charset=windows-1250';
begin
    utl_mail.send (
        p_sender,
        p_receip,
        p_cc, -- cc
        null, -- bcc
        p_subject,
        p_message,
        l_type, --v_type, 
        null, --priority
        null); -- replyto
    l_rc := 'Y';
    return l_rc;
end;

/
--------------------------------------------------------
--  DDL for Function TO_BASE_36
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "BCPMS_OWNER"."TO_BASE_36" (n integer) return varchar2
is
  q integer;
  r varchar2(100);
begin
  q := n;
  while q >= 36 loop
     r := chr(mod(q,36)+case when mod(q,36) < 10 then 48 else 55 end) || r;
     q := floor(q/36);
  end loop;
  r := chr(mod(q,36)+case when mod(q,36) < 10 then 48 else 55 end) || r;
  return lpad(r,3,'0');
end;

/
